window.XLSX={utils:{json_to_sheet:(rows)=>rows,book_new:()=>({sheets:{}}),book_append_sheet:(wb,ws,name)=>wb.sheets[name]=ws},writeFile:(wb,name)=>{const keys=new Set();Object.values(wb.sheets).forEach(rows=>rows.forEach(r=>Object.keys(r).forEach(k=>keys.add(k))));const cols=[...keys];const lines=[cols.join(',')];const first=Object.values(wb.sheets)[0]||[];first.forEach(r=>lines.push(cols.map(c=>`"${String(r[c]??'').replaceAll('"','""')}"`).join(',')));const blob=new Blob(['\uFEFF'+lines.join('\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.replace(/\.xlsx$/,'')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}};
